#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>

#define KEY_SIZE 32
#define IV_SIZE 16
#define MAX_REPO_LEN 256
#define TRUSTED_ORG "github.com/acmecorp"

typedef struct {
    char repo_url[MAX_REPO_LEN];
    unsigned char encrypted_token[512];
    int token_len;
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} pipeline_ctx;

static int normalize_url(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    for (i = 0; i < strlen(input) && j < outlen - 1; i++) {
        /* Only allow printable ASCII in URLs - reject anything >= 0x80 */
        if ((unsigned char)input[i] >= 0x80) {
            return -1;
        }
        /* Strip trailing slashes and normalize case for scheme */
        if (i < 8) {
            output[j++] = (input[i] >= 'A' && input[i] <= 'Z') ?
                          input[i] + 32 : input[i];
        } else {
            output[j++] = input[i];
        }
    }
    /* Remove trailing slash */
    if (j > 0 && output[j-1] == '/') j--;
    output[j] = '\0';
    return 0;
}

static int validate_repo_origin(const char *repo_url) {
    char normalized[MAX_REPO_LEN];
    if (normalize_url(repo_url, normalized, sizeof(normalized)) != 0) {
        return -1;
    }

    /* Check that the repo belongs to our trusted organization */
    const char *path_start = strstr(normalized, "://");
    if (!path_start) return -1;
    path_start += 3;

    /* Verify the hostname and org path match our trusted org */
    if (strncmp(path_start, TRUSTED_ORG, strlen(TRUSTED_ORG)) == 0) {
        char next_char = path_start[strlen(TRUSTED_ORG)];
        if (next_char == '/' || next_char == '\0') {
            return 0; /* Trusted */
        }
    }
    return -1;
}

static int decrypt_deploy_token(pipeline_ctx *ctx, char *token_out, int max_len) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    int len, plaintext_len;

    if (!cipher_ctx) return -1;

    /* Ensure there is room for the largest possible plaintext plus NUL.
       AES-256-CBC output is at most token_len bytes. */
    if (max_len <= 0 || ctx->token_len < 0 || ctx->token_len >= max_len) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    if (EVP_DecryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL,
                           ctx->key, ctx->iv) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    if (EVP_DecryptUpdate(cipher_ctx, (unsigned char*)token_out, &len,
                          ctx->encrypted_token, ctx->token_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    plaintext_len = len;

    if (EVP_DecryptFinal_ex(cipher_ctx, (unsigned char*)token_out + len, &len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    plaintext_len += len;

    if (plaintext_len < 0 || plaintext_len >= max_len) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    token_out[plaintext_len] = '\0';

    EVP_CIPHER_CTX_free(cipher_ctx);
    return plaintext_len;
}

static int execute_clone(const char *repo_url, const char *token) {
    /* Use execvp instead of system() to prevent command injection */
    char auth_url[1024];
    snprintf(auth_url, sizeof(auth_url), "https://%s@%s",
             token, repo_url + 8);

    pid_t pid = fork();
    if (pid == 0) {
        execlp("git", "git", "clone", auth_url, "/workspace/build", NULL);
        _exit(127);
    } else if (pid > 0) {
        int status;
        waitpid(pid, &status, 0);
        /* Clear auth_url from child's memory isn't possible, but parent clears */
        memset(auth_url, 0, sizeof(auth_url));
        return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
    }
    return -1;
}

int pipeline_run(const char *requested_repo) {
    pipeline_ctx ctx;
    char token[256];

    memset(&ctx, 0, sizeof(ctx));
    strncpy(ctx.repo_url, requested_repo, MAX_REPO_LEN - 1);

    /* Load encrypted token from secure storage */
    FILE *f = fopen("/etc/ci/deploy_token.enc", "rb");
    if (!f) { fprintf(stderr, "Cannot read token store\n"); return -1; }
    ctx.token_len = fread(ctx.encrypted_token, 1, sizeof(ctx.encrypted_token), f);
    fclose(f);
    if (ctx.token_len <= 0) {
        fprintf(stderr, "Empty or unreadable token store\n");
        memset(&ctx, 0, sizeof(ctx));
        return -1;
    }

    /* Load key from HSM-backed keyfile */
    f = fopen("/etc/ci/master.key", "rb");
    if (!f) { fprintf(stderr, "Cannot read master key\n"); return -1; }
    if (fread(ctx.key, 1, KEY_SIZE, f) != KEY_SIZE ||
        fread(ctx.iv, 1, IV_SIZE, f) != IV_SIZE) {
        fprintf(stderr, "Master key file truncated\n");
        fclose(f);
        memset(&ctx, 0, sizeof(ctx));
        return -1;
    }
    fclose(f);

    /* Validate the repository is from our trusted org */
    if (validate_repo_origin(ctx.repo_url) != 0) {
        fprintf(stderr, "[SECURITY] Repository not in trusted org: %s\n", ctx.repo_url);
        memset(&ctx, 0, sizeof(ctx));
        return -1;
    }

    /* Decrypt the deploy token */
    if (decrypt_deploy_token(&ctx, token, sizeof(token)) < 0) {
        fprintf(stderr, "Token decryption failed\n");
        memset(token, 0, sizeof(token));
        memset(&ctx, 0, sizeof(ctx));
        return -1;
    }

    /* Execute the clone with credentials */
    int ret = execute_clone(ctx.repo_url, token);

    /* Secure cleanup */
    memset(token, 0, sizeof(token));
    memset(&ctx, 0, sizeof(ctx));
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <repo_url>\n", argv[0]);
        return 1;
    }
    return pipeline_run(argv[1]);
}
